const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=value=>Number.isFinite(value)?String(Number(value.toPrecision(7))):'—';
export function abilityDebugPage(object,{section='attributes',offset=0,limit=64}={}){
 if(!['attributes','abilities','effects'].includes(section)||!Number.isInteger(offset)||offset<0||!Number.isInteger(limit)||limit<1||limit>256)throw Error('능력 진단 구역·페이지를 확인하세요.');const state=object?.gameplayDebug?.ability;if(!state)return {ready:false,total:0,items:[]};const rows=section==='attributes'?Object.entries(state.attributes).map(([name,row])=>({name,...row})):section==='abilities'?Object.entries(state.abilities).map(([asset,row])=>({asset,...row})):state.effects;return {ready:true,owner:object.id,time:state.time,section,total:rows.length,offset,items:structuredClone(rows.slice(offset,offset+limit))};
}
const signature=state=>JSON.stringify([Object.keys(state?.attributes||{}),Object.keys(state?.abilities||{}),(state?.effects||[]).map(e=>e.handle)]);
export function abilityReadout(state={}){
 const cell=(key,value)=>'<td data-ability-field="'+esc(key)+'" title="'+esc(value)+'">'+esc(typeof value==='number'?(/\|(cooldown|remaining)$/.test(key)&&value>=0?value.toFixed(2):number(value)):value)+'</td>',attributes=Object.entries(state.attributes||{}).map(([name,row])=>'<tr><th scope=row>'+esc(name)+'</th>'+['base','current','min','max'].map(key=>cell('attribute|'+name+'|'+key,row[key])).join('')+'</tr>').join(''),abilities=Object.entries(state.abilities||{}).map(([asset,row])=>'<tr><th scope=row title="'+esc(asset)+'">'+esc(asset.split('/').at(-1).replace('.hbability.json',''))+'</th>'+cell('ability|'+asset+'|active',row.active?'활성':'대기')+cell('ability|'+asset+'|cooldown',row.cooldown)+'</tr>').join(''),effects=(state.effects||[]).map(row=>'<tr><th scope=row title="'+esc(row.asset)+'">'+esc(row.asset.split('/').at(-1).replace('.hbeffect.json',''))+'</th>'+cell('effect|'+row.handle+'|stacks',row.stacks)+cell('effect|'+row.handle+'|remaining',row.remaining<0?'∞':row.remaining)+'</tr>').join('');
 return '<div class="ability-readout" data-ability-readout data-ability-structure="'+esc(signature(state))+'"><table><thead><tr><th>속성</th><th>기본</th><th>현재</th><th>최소</th><th>최대</th></tr></thead><tbody>'+attributes+'</tbody></table><table><thead><tr><th>능력</th><th>상태</th><th>재사용(s)</th></tr></thead><tbody>'+abilities+'</tbody></table>'+(effects?'<table><thead><tr><th>효과</th><th>중첩</th><th>남은(s)</th></tr></thead><tbody>'+effects+'</tbody></table>':'')+'</div>';
}
export function updateAbilityReadout(root,object){
 const element=root.querySelector('[data-ability-readout]'),state=object?.gameplayDebug?.ability;if(!element||!state)return;
 if(element.dataset.abilityStructure!==signature(state)){element.outerHTML=abilityReadout(state);return;}
 const effects=new Map(state.effects.map(e=>[e.handle,e]));for(const cell of element.querySelectorAll('[data-ability-field]')){const [section,key,field]=cell.dataset.abilityField.split('|'),row=section==='attribute'?state.attributes[key]:section==='ability'?state.abilities[key]:effects.get(key),value=row?.[field],text=field==='active'?(value?'활성':'대기'):field==='remaining'&&value<0?'∞':typeof value==='number'?(['cooldown','remaining'].includes(field)?value.toFixed(2):number(value)):String(value??'—');if(cell.textContent!==text)cell.textContent=text;if(cell.title!==String(value))cell.title=String(value);}
}
